from collections import deque


class ConnectGame:
    def __init__(self, board):
        # Each row is indented one space per row; strip the leading spaces to
        # get the cells. Row r then has r + 1 cells.
        self.board = [
            row.strip().replace(" ", "")
            for row in board.splitlines()
        ]
        self.rows = len(self.board)
        self.cols = len(self.board[0]) if self.board else 0

    def _neighbors(self, r, c):
        # Hex adjacency on the skewed parallelogram.
        for dr, dc in ((-1, 0), (-1, -1), (0, -1), (1, -1), (1, 0), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < self.rows and 0 <= nc < len(self.board[nr]):
                yield nr, nc

    def _connects(self, player, edges):
        # Flood fill from every cell of `player` touching the start edges and
        # check whether any reached cell touches the target edges.
        seen = set()
        queue = deque()
        for r in range(self.rows):
            for c in edges(self.board[r], r, c, self.cols):
                pass
        for r in range(self.rows):
            for c, is_start in self._edge_cells(edges):
                if is_start and self.board[r][c] == player:
                    seen.add((r, c))
                    queue.append((r, c))
        while queue:
            r, c = queue.popleft()
            if self._is_target(r, c, edges):
                return True
            for nr, nc in self._neighbors(r, c):
                if (nr, nc) not in seen and self.board[nr][nc] == player:
                    seen.add((nr, nc))
                    queue.append((nr, nc))
        return False

    def _edge_cells(self, edges):
        for r in range(self.rows):
            for c in range(len(self.board[r])):
                yield c, edges(r, c)

    def _is_target(self, r, c, edges):
        return edges(r, c)

    def get_winner(self):
        def x_edges(r, c):
            return c == 0 or c == r

        def o_edges(r, c):
            return r == 0 or r == self.rows - 1

        x_wins = self._connects("X", x_edges)
        o_wins = self._connects("O", o_edges)
        if x_wins and o_wins:
            return ""
        if x_wins:
            return "X"
        if o_wins:
            return "O"
        return ""

