from collections import deque


class ConnectGame:
    def __init__(self, board):
        # Each row is indented one space per row; strip the leading spaces to
        # get the cells. Every row then has the same number of cells, and the
        # one-space skew is what makes the parallelogram a Hex board.
        self.board = [
            row.strip().replace(" ", "")
            for row in board.splitlines()
        ]
        self.rows = len(self.board)

    def _neighbors(self, r, c):
        # Hex adjacency on the skewed parallelogram.
        for dr, dc in ((-1, 0), (-1, -1), (0, -1), (1, -1), (1, 0), (0, 1)):
            nr, nc = r + dr, c + dc
            if 0 <= nr < self.rows and 0 <= nc < len(self.board[nr]):
                yield nr, nc

    def _connects(self, player, start_edge, target_edge):
        # Flood fill from every cell of `player` touching the start edges and
        # check whether any reached cell touches the target edges.
        seen = set()
        queue = deque()
        for r in range(self.rows):
            for c in range(len(self.board[r])):
                if start_edge(r, c) and self.board[r][c] == player:
                    seen.add((r, c))
                    queue.append((r, c))
        while queue:
            r, c = queue.popleft()
            if target_edge(r, c):
                return True
            for nr, nc in self._neighbors(r, c):
                if (nr, nc) not in seen and self.board[nr][nc] == player:
                    seen.add((nr, nc))
                    queue.append((nr, nc))
        return False

    def get_winner(self):
        x_wins = self._connects(
            "X",
            lambda r, c: c == 0,
            lambda r, c: c == len(self.board[r]) - 1,
        )
        o_wins = self._connects(
            "O",
            lambda r, c: r == 0,
            lambda r, c: r == self.rows - 1,
        )
        if x_wins and o_wins:
            return ""
        if x_wins:
            return "X"
        if o_wins:
            return "O"
        return ""

